//! `odc-bindings` writes `crates/odc-gpu-rank/src/bindings.rs`: the kernel structures and
//! constants the GPU rank helper asks the GPU drivers with, generated by bindgen from the kernel's
//! own headers as installed, never written by hand (owner, 2026-10-28; Phase 6 plan, Task 9).
//! It's a dev-only tool, never shipped, and the only program that needs clang (libclang): the
//! build, the tests, CI and the package use the committed file.

use std::io::Write;
use std::path::Path;
use std::process::{Command, ExitCode, Stdio};
use std::{env, fs, thread};

use bindgen::{Formatter, RustEdition, RustTarget};

const USAGE: &str = "usage: odc-bindings [--check]

Writes crates/odc-gpu-rank/src/bindings.rs from the installed kernel headers
drm/amdgpu_drm.h, drm/i915_drm.h and drm/xe_drm.h, with bindgen. With --check,
writes nothing and fails when the committed file differs from what the headers
give. Needs clang (libclang) and rustfmt.";

/// The generated file, from the workspace's root.
const OUTPUT: &str = "crates/odc-gpu-rank/src/bindings.rs";

/// Where the headers are installed (Arch Linux's `linux-api-headers`).
const INCLUDE_DIR: &str = "/usr/include";

/// The headers, in the order their notices are copied: the three drivers' and `drm.h`, which
/// they include and which defines the ioctl base and the driver command base.
const HEADERS: [&str; 4] = [
    "drm/drm.h",
    "drm/amdgpu_drm.h",
    "drm/i915_drm.h",
    "drm/xe_drm.h",
];

/// The structures the helper passes to the kernel; bindgen adds those they contain. The enum
/// holds `I915_MEMORY_CLASS_DEVICE`.
const TYPES: [&str; 8] = [
    "drm_amdgpu_info",
    "drm_amdgpu_info_device",
    "drm_xe_device_query",
    "drm_xe_query_config",
    "drm_i915_query",
    "drm_i915_query_item",
    "drm_i915_query_memory_regions",
    "drm_i915_gem_memory_class",
];

/// The constants the requests and the kind flags need. The ioctl base joins the plan's list: the
/// helper builds the request numbers from it as `drm.h`'s `DRM_IOW` and `DRM_IOWR` do.
const VARS: [&str; 11] = [
    "DRM_IOCTL_BASE",
    "DRM_COMMAND_BASE",
    "DRM_AMDGPU_INFO",
    "AMDGPU_INFO_DEV_INFO",
    "AMDGPU_IDS_FLAGS_FUSION",
    "DRM_XE_DEVICE_QUERY",
    "DRM_XE_DEVICE_QUERY_CONFIG",
    "DRM_XE_QUERY_CONFIG_FLAGS",
    "DRM_XE_QUERY_CONFIG_FLAG_HAS_VRAM",
    "DRM_I915_QUERY",
    "DRM_I915_QUERY_MEMORY_REGIONS",
];

fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();
    let check = match args.as_slice() {
        [] => false,
        [flag] if flag == "--check" => true,
        [flag] if flag == "-h" || flag == "--help" => {
            println!("{USAGE}");
            return ExitCode::SUCCESS;
        }
        _ => {
            eprintln!("{USAGE}");
            return ExitCode::from(2);
        }
    };
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .join(OUTPUT);
    let text = match generate() {
        Ok(text) => text,
        Err(e) => {
            eprintln!("odc-bindings: {e}");
            return ExitCode::FAILURE;
        }
    };
    if check {
        match fs::read_to_string(&path) {
            Ok(committed) if committed == text => {
                println!("{OUTPUT} is what the installed headers give");
                ExitCode::SUCCESS
            }
            Ok(_) => {
                eprintln!(
                    "odc-bindings: {OUTPUT} differs from what the installed headers give; \
                     run `cargo run -p odc-bindings` and review the change"
                );
                ExitCode::FAILURE
            }
            Err(e) => {
                eprintln!("odc-bindings: {OUTPUT}: {e}");
                ExitCode::FAILURE
            }
        }
    } else {
        match fs::write(&path, text) {
            Ok(()) => {
                println!("{OUTPUT} written");
                ExitCode::SUCCESS
            }
            Err(e) => {
                eprintln!("odc-bindings: {OUTPUT}: {e}");
                ExitCode::FAILURE
            }
        }
    }
}

/// The file's text: the preamble with the headers' notices, then bindgen's output, formatted by
/// rustfmt as `cargo fmt` formats the workspace.
fn generate() -> Result<String, String> {
    let mut notices = Vec::new();
    let mut includes = String::new();
    for header in HEADERS {
        let path = Path::new(INCLUDE_DIR).join(header);
        let text = fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        notices.push((header, notice(&text)));
        includes.push_str(&format!("#include \"{}\"\n", path.display()));
    }
    // The workspace's Rust version, so the code may use what the helper's edition 2024 needs.
    let target: RustTarget = env!("CARGO_PKG_RUST_VERSION")
        .parse()
        .map_err(|e| format!("the workspace's Rust version: {e}"))?;
    let mut builder = bindgen::Builder::default()
        .header_contents("odc-gpu-rank.h", &includes)
        // Arch Linux on x86_64 is the only platform OpenDeepCool supports (deny.toml).
        .clang_arg("--target=x86_64-unknown-linux-gnu")
        .rust_target(target)
        .rust_edition(RustEdition::Edition2024)
        .formatter(Formatter::None)
        .disable_header_comment()
        .generate_comments(false)
        .derive_default(true)
        .prepend_enum_name(false)
        .wrap_unsafe_ops(true)
        .layout_tests(true);
    for name in TYPES {
        builder = builder.allowlist_type(name);
    }
    for name in VARS {
        builder = builder.allowlist_var(name);
    }
    let bindings = builder.generate().map_err(|e| format!("bindgen: {e}"))?;
    rustfmt(&format!("{}{bindings}", preamble(&notices)))
}

/// A header's notice: its lines before the first preprocessor line, each without trailing
/// spaces, and without the blank lines that end it.
fn notice(header: &str) -> String {
    let lines: Vec<&str> = header
        .lines()
        .take_while(|line| !line.starts_with('#'))
        .map(str::trim_end)
        .collect();
    let end = lines
        .iter()
        .rposition(|line| !line.is_empty())
        .map_or(0, |i| i + 1);
    lines[..end].join("\n")
}

/// The note that the file is generated, the headers' notices, and the lints the generated code
/// needs allowed. The module's `unsafe` (bindgen's `Default` for unions and its flexible-array
/// helper) is one of the two places the helper allows it (Phase 6 plan, Task 9).
fn preamble(notices: &[(&str, String)]) -> String {
    let mut text = String::from(
        "// Generated by `cargo run -p odc-bindings` (tools/bindings/) with bindgen from the kernel's\n\
         // headers as installed. Don't edit it: run the command again. `cargo run -p odc-bindings --\n\
         // --check` fails when this file differs from what the headers give, and the layout checks\n\
         // after each structure fail the build when an edit changes its size, its alignment or a\n\
         // field's offset.\n\
         //\n\
         // The structures and constants come from these headers, whose notices follow. The integer\n\
         // types they're made of (`__u32` and the like) are the kernel's own, from `linux/types.h`.\n",
    );
    for (header, notice) in notices {
        text.push_str(&format!("//\n// {header}:\n//\n"));
        for line in notice.lines() {
            if line.is_empty() {
                text.push_str("//\n");
            } else {
                text.push_str(&format!("//   {line}\n"));
            }
        }
    }
    text.push_str(
        "\n#![allow(unsafe_code)]\n\
         #![allow(dead_code, non_camel_case_types, non_upper_case_globals)]\n\n",
    );
    text
}

/// `source` formatted by rustfmt, as `cargo fmt` formats an edition 2024 crate without a
/// `rustfmt.toml`.
fn rustfmt(source: &str) -> Result<String, String> {
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("rustfmt: {e}"))?;
    let mut stdin = child.stdin.take().ok_or("rustfmt: no input pipe")?;
    let input = source.to_owned();
    // Written from another thread, so a full output pipe can't block the input.
    let writer = thread::spawn(move || stdin.write_all(input.as_bytes()));
    let output = child
        .wait_with_output()
        .map_err(|e| format!("rustfmt: {e}"))?;
    writer
        .join()
        .map_err(|_| "rustfmt: the input thread panicked")?
        .map_err(|e| format!("rustfmt: {e}"))?;
    if !output.status.success() {
        return Err(format!(
            "rustfmt failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    String::from_utf8(output.stdout).map_err(|e| format!("rustfmt: {e}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_notice_is_the_comment_before_the_first_preprocessor_line() {
        let header = "/* SPDX-License-Identifier: MIT */  \n/*\n * Copyright 2023 Someone \n */\n\n\
                      #ifndef _X_H_\n/* not this */\n";
        assert_eq!(
            notice(header),
            "/* SPDX-License-Identifier: MIT */\n/*\n * Copyright 2023 Someone\n */"
        );
        assert_eq!(notice("#ifndef _X_H_\n"), "");
    }

    #[test]
    fn the_preamble_copies_each_notice_as_comments_before_the_lints() {
        let text = preamble(&[("drm/x.h", "/*\n * Copyright\n *\n */".to_owned())]);
        assert!(text.starts_with("// Generated by `cargo run -p odc-bindings`"));
        assert!(text.contains("//\n// drm/x.h:\n//\n//   /*\n//    * Copyright\n//    *\n"));
        assert!(text.contains("\n\n#![allow(unsafe_code)]\n"));
        assert!(
            text.lines()
                .filter(|line| !line.starts_with("#!") && !line.is_empty())
                .all(|line| line.starts_with("//")),
            "{text}"
        );
        assert!(text.lines().all(|line| line == line.trim_end()));
    }
}
